/** Public rendering seam: diagnostics and pinned docs evidence consume the same operator projection. */
export function renderManagedHostRunDoctorSection(
  managedHostRuns: ManagedHostRunRuntimeScan,
  managedHostRunGc: ManagedHostRunGcResult | null = null,
  brief = false,
): string[] {
  const lines = ['Managed host runs:'];
  lines.push(
    `  active=${managedHostRuns.active} terminal=${managedHostRuns.terminal} corrupt=${managedHostRuns.corrupt} `
    + `gcEligible=${managedHostRuns.eligibleForGc} retentionMs=${managedHostRuns.retentionMs}`,
  );
  if (!brief) {
    for (const run of managedHostRuns.runs) {
      lines.push(
        `  - ${run.runId} state=${run.state} worker=${run.workerLiveness} `
        + `heartbeatAt=${run.workerHeartbeatAt ?? 'none'} providerProgress=${run.providerProgressMode}:${run.lastProviderProgressAt ?? 'none'} `
        + `deadlineAt=${run.deadlineAt ?? 'unknown'} cancelAt=${run.cancelRequestedAt ?? 'none'} `
        + `residual=${run.residualProcessGroup ?? 'unknown'} replacementSafe=${run.replacementSafe ?? 'unknown'} `
        + `terminalReason=${run.terminalReason ?? 'none'} retentionExpired=${run.retentionExpired} oneShotInputs=${run.hasUnconsumedOneShotInputs}`,
      );
      if (run.error) lines.push(`    error: ${run.error}`);
    }
  }
  if (managedHostRunGc) {
    for (const runId of managedHostRunGc.removed) lines.push(`  ✓ removed expired terminal run ${runId}`);
    for (const runId of managedHostRunGc.archivedReceipts) lines.push(`  ✓ preserved sealed receipt archive ${runId}`);
    for (const failed of managedHostRunGc.failed) lines.push(`  ✗ failed to remove ${failed.runId}: ${failed.error}`);
  } else if (managedHostRuns.eligibleForGc > 0) {
    lines.push('  → Run lattice doctor --repair to remove only terminal runs beyond retention; active/corrupt/one-shot-input runs stay protected.');
  }
  lines.push('');
  return lines;
}

export function createDoctorHandlers(ctx: HandlerContext) {
  const { root, store } = ctx;

  return {
    // B-623a x B-7c05 merge: async (host burn scan awaits the store sweeps) AND
    // the brief/full render-only flags from main.
    async doctor(args?: { format?: 'text' | 'json'; limit?: number; repair?: boolean; full?: boolean; brief?: boolean }): Promise<string | object> {
      const limit = args?.limit ?? 1000;
      // B-7c05 CHK-004: RENDER-ONLY brief text mode, active ONLY on explicit
      // brief:true (injected by the CLI seam for bare invocations after
      // resolving flag > env > brief default). In-process callers and
      // --format=json keep today's full shape. Brief trims exactly the two
      // heavy sections (Recent issues detail, Validation scan detail) to
      // one-liners/counts; every failing/warning section stays visible.
      const brief = args?.brief === true && args?.format !== 'json';
      const issues = readHealthIssues(limit);
      const summary = summarizeHealthIssues(issues);
      const codex = runCodexAdapterChecks(root, {
        executeHeartbeats: true,
        registryNames: ctx.getAllToolNames?.(),
      });
      const validation = scanValidationSetup(root);
      const runtime = runRuntimeEnvironmentChecks(root);
      // B-097f: Claude agent prompts are runtime-owned (single source =
      // global ~/.claude/agents). Surface the mode + any stale project-local
      // managed agent files so historical projects are diagnosable.
      const projectAgentScan = scanProjectLocalManagedAgents(root);
      const agentAssets = {
        agentAssetMode: AGENT_ASSET_MODE_RUNTIME_OWNED,
        projectLocalManagedFiles: projectAgentScan.managedFiles,
        hasStaleProjectLocal: projectAgentScan.managedFiles.length > 0,
      };
      // B-1637: resolve the gitRoot ONCE and thread it as the cwd into every git
      // probe below, so wrapper-root projects (metadataRoot != gitRoot) no longer
      // print leading `fatal: not a git repository` lines. Falls back to `root`
      // when no gitRoot resolves → byte-identical for plain repos.
      const gitProbeCwd = resolveDoctorGitCwd(root);
      let trackedRuntimeArtifacts = scanTrackedRuntimeArtifacts(root, gitProbeCwd);
      let managedHostRuns = scanManagedHostRunRuntime(root);
